#pragma once
// Independent Host reference, never included by the DSP arithmetic header.
namespace forwardsoftmaxreference {
inline uint32_t bits(float x){uint32_t u;std::memcpy(&u,&x,4);return u;}
inline float number(uint32_t u){float x;std::memcpy(&x,&u,4);return x;}
struct Result {one::FV maximum,shift,exponent,denominator,p;};
inline Result evaluate(const one::FV& x){Result v;v.maximum.resize(32);v.shift.resize(1024);v.exponent.resize(1024);v.denominator.resize(32);v.p.resize(1024);for(unsigned r=0;r<32;++r){auto first=x.begin()+r*32;float maximum=*std::max_element(first,first+32);v.maximum[r]=maximum;for(unsigned c=0;c<32;++c){unsigned i=r*32+c;v.shift[i]=float(double(x[i])-double(maximum));v.exponent[i]=std::exp(v.shift[i]);}float total=0;for(unsigned c=0;c<32;++c)total=float(double(total)+double(v.exponent[r*32+c]));v.denominator[r]=total;for(unsigned c=0;c<32;++c)v.p[r*32+c]=float(double(v.exponent[r*32+c])/double(total));}return v;}
// Replays max/shift/reduce/divide from RECEIVED exponent words, independently
// auditing ordered arithmetic without treating Host libm as a DSP exp oracle.
inline unsigned receipt(const std::vector<uint32_t>& r,const std::array<one::FV,2>& inputs,const std::array<one::FV,2>& outputs,unsigned marker,unsigned& last,double& expAbs,unsigned& expHostWords){if(r.size()!=8328||r[0]!=marker||r[1]<=last||r[2]!=2048||r[3]!=2048||r[5]!=81||r[6]!=32)throw std::runtime_error("FORWARD_SOFTMAX_RECEIPT_HEADER");last=r[1];unsigned mismatches=0;for(unsigned h=0;h<2;++h){auto ref=evaluate(inputs[h]);for(unsigned i=0;i<1024;++i){mismatches+=r[8+h*1024+i]!=bits(inputs[h][i]);mismatches+=r[2120+h*1024+i]!=bits(ref.shift[i]);mismatches+=r[6280+h*1024+i]!=bits(outputs[h][i]);float e=number(r[4168+h*1024+i]);if(!std::isfinite(e)||e<0)throw std::runtime_error("FORWARD_SOFTMAX_EXP_NONFINITE");expAbs=std::max(expAbs,std::fabs(double(e)-std::exp(double(ref.shift[i]))));expHostWords+=bits(e)!=bits(ref.exponent[i]);}for(unsigned row=0;row<32;++row){mismatches+=r[2056+h*32+row]!=bits(ref.maximum[row]);float total=0;for(unsigned c=0;c<32;++c)total=float(double(total)+double(number(r[4168+h*1024+row*32+c])));mismatches+=r[6216+h*32+row]!=bits(total);for(unsigned c=0;c<32;++c){float e=number(r[4168+h*1024+row*32+c]);float p=float(double(e)/double(total));mismatches+=bits(outputs[h][row*32+c])!=bits(p);}}}return mismatches;}
}
